use std::fs
use std::process

fn fail() {
    println("error")
    process::exit(1)
}

fn parse_row(line: string, n: int) -> Vec<int> {
    let mut out: Vec<int> = []
    for p in line.split_whitespace() {
        match p.parse::<int>() {
            Ok(v) => out.push(v),
            Err(_) => fail(),
        }
    }
    if out.len() as int != n {
        fail()
    }
    out
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
    }
    let hd = parse_row(lines[0], 2)
    let r = hd[0]
    let c = hd[1]
    if r < 1 || c < 1 {
        fail()
    }
    if (lines.len() as int) < r + 1 {
        fail()
    }
    let mut g: Vec<Vec<int>> = []
    let mut i = 0
    while i < r {
        g.push(parse_row(lines[(i + 1) as usize], c))
        i += 1
    }
    let mut res: Vec<string> = []
    let mut top = 0
    let mut bot = r - 1
    let mut left = 0
    let mut right = c - 1
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            res.push("${g[top as usize][j as usize]}")
            j += 1
        }
        top += 1
        j = top
        while j <= bot {
            res.push("${g[j as usize][right as usize]}")
            j += 1
        }
        right -= 1
        if top <= bot {
            j = right
            while j >= left {
                res.push("${g[bot as usize][j as usize]}")
                j -= 1
            }
            bot -= 1
        }
        if left <= right {
            j = bot
            while j >= top {
                res.push("${g[j as usize][left as usize]}")
                j -= 1
            }
            left += 1
        }
    }
    println(res.join(" "))
}

